var lingrad, radgrad;
let n_colors= 12; //number of colors in the array 
let tl, tr, bl, br ;
let temp_top= [];
let temp_bottom= [];

let kiwi = []; 
let rows = 4;
let cols = 2;

let size;

function setup() {
	size = max(windowWidth, windowHeight)

  createCanvas(size, size);
  noStroke();
  reset_all();
}  


function reset_all(){

	//initialize radial gradient background
  radgrad = drawingContext.createRadialGradient(width/2, height/2, width/4, width/2,height/2, width/2);
  radgrad.addColorStop(0, 'rgb(255, 255, 255)');
  radgrad.addColorStop(1, 'rgb(237, 235, 228)');

	//initialize 4 colors for gradients
  let rn = floor(random(n_colors));
  tl =  color(skys[rn].topc);

  rn = floor(random(n_colors));  
  br =  color(skys[rn].midc);

  rn = floor(random(n_colors));
  tr =  color(skys[rn].botc);

  rn = floor(random(n_colors));
  bl =  color(skys[rn].topc);

  for (let j=0; j<cols; j++) {
    temp_top[j] = lerpColor(color(tl), color(tr), j/(cols));
  }

  for (let j=0; j<rows; j++) {
   temp_bottom[j] = lerpColor(color(bl), color(br), j/(rows));
  }


//initialize all the birbs - (vector position, width, height, tangent length, index i, index j, number of stripes, color 1, color 2)
// class Birb is in tab2
// there are shape  and movement defined
// also eyes, I know Raph will try to make them bigger

  for (let i=0; i<cols; i++){
    for (let j=0; j<rows; j++) {
      kiwi[i*rows+j] = new Birb(createVector(random(width*0.1, width*0.24)+(i)*random(width*0.56, width*0.7), width*0.20+j*random(width*0.12, width*0.2)), 
                    random(width*0.2, width*0.23), 
                    random(width*0.2, width*0.23), 
                    random(0.5, 0.55), 
                    i, j, 
                    floor(random(3,5)), 
                    temp_top[i], temp_bottom[j]);
    }
  }
}



function mouseReleased() {
	 reset_all();
}


function draw() {

  background(247, 245, 238);

  drawingContext.fillStyle = radgrad;
  rect(0,0, width, height);

	//glitch try 
	var rn = floor(random(0, kiwi.length));
	let temp = kiwi[rn].ho;
	if (random(1)<0.01) {
  	kiwi[rn].ho = 0;
	}

	//display kiwis and make them jump
   for (let i=0; i<cols; i++){
    for (let j=0; j<rows; j++) {
      kiwi[i*rows+j].display_new02(); 
      kiwi[i*rows+j].move();
    }
  }

	//return back from glitch
  kiwi[rn].ho = temp;
}


